local function _bx(a, b)
  local r, p = 0, 1
  a = a % 256; b = b % 256
  for _ = 1, 8 do
    if (a % 2) ~= (b % 2) then r = r + p end
    a = math.floor(a / 2); b = math.floor(b / 2); p = p * 2
  end
  return r
end

local function _ks(len, idx)
  local s = 0xA5A5F00D
  for i = 1, #_M do
    s = (s * 1664525 + _M[i] + 1013904223) % 4294967296
  end
  s = (s * 1664525 + (idx * 2654435761) + 1013904223) % 4294967296
  local out = table.create(len)
  for i = 1, len do
    s = (s * 1664525 + 1013904223) % 4294967296
    out[i] = math.floor(s / 65536) % 256
  end
  return out
end

local function _b64(data)
  local alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  data = string.gsub(data, "[^A-Za-z0-9+/=]", "")
  local out = {}
  local buf, nbits = 0, 0
  for i = 1, #data do
    local c = data:sub(i, i)
    if c == "=" then break end
    local v = (alpha:find(c, 1, true) or 1) - 1
    buf = buf * 64 + v
    nbits = nbits + 6
    if nbits >= 8 then
      nbits = nbits - 8
      local byte = math.floor(buf / (2 ^ nbits)) % 256
      out[#out + 1] = string.char(byte)
      buf = buf % (2 ^ nbits)
    end
  end
  return table.concat(out)
end

local function _unpack(enc, idx0)
  local mixed = _b64(enc)
  local salt = _bx(0x3C, (idx0 * 31 + 7) % 256)
  local stripped = {}
  local n = 0
  for i = 1, #mixed do
    if (i % 6) ~= 0 then
      n = n + 1
      stripped[n] = string.byte(mixed, i)
    end
  end
  local raw = table.create(n)
  for i = 1, n do
    raw[i] = stripped[n - i + 1]
  end
  for i = 1, n do
    local b = raw[i]
    b = _bx(b, _bx(salt, (i - 1) % 256))
    b = ((b * 16) % 256) + math.floor(b / 16)
    raw[i] = b
  end
  local ks = _ks(n, idx0)
  local chars = table.create(n)
  for i = 1, n do
    chars[i] = string.char(_bx(raw[i], ks[i]))
  end
  return table.concat(chars)
end

local parts = table.create(#_S)
for i = 1, #_S do
  local ok, body = pcall(_unpack, _S[i], i - 1)
  if not ok or type(body) ~= "string" or #body < 32 then
    error("[KFC] segment " .. i .. " integrity failure", 0)
  end
  parts[i] = body
end

local src = table.concat(parts)
parts = nil
_S = nil
_M = nil

local fn, err = loadstring(src)
if not fn then
  error("[KFC] compile: " .. tostring(err), 0)
end
src = nil
fn()
end
